    "gifts": [
      "Al‑Mateen tells you that behind every fragile thing in your life stands a Lord whose power never cracks, fades, or gets tired. Human strength rises and falls, emotions swing, plans collapse; the strength of Al‑Mateen does not.",
      "This Name comforts a heart that feels worn out or pushed to its limits. You are not asked to be unbreakable; you are asked to cling to the One who is. When you feel like you cannot hold on, Al‑Mateen is the One holding you.",
      "It also reframes how you see worldly power. Governments, systems, and powerful individuals appear “solid,” but history shows how quickly they can crumble. True firmness belongs only to the One whose will is never overpowered."
    ],
    "practicalWays": [
      "When you feel weak, overwhelmed, or on the verge of giving up, speak to Allah explicitly as Al‑Mateen. Say in your own words: “O Allah, You are the Strong, the Firm; support me with strength from You, because I am weak.”",
      "Ask Al‑Mateen for thabat: firmness in faith, consistency in worship, and stability in character. Make this especially when things are going well, not only in crises, so that your heart is prepared before the storm comes.",
      "Build your life on what is firm with Allah, not on what is fragile with people: base key decisions on what pleases Him, not on short‑lived trends or approval. Remember that whatever is connected to Al‑Mateen inherits a share of stability.",
      "When you succeed or endure something hard, do not narrate the story as “I was so strong.” Instead, train yourself to say, “Allah gave me strength.” This shifts your heart from ego to gratitude and makes you more likely to receive ongoing support.",
      "Teach children simply: Allah is Al‑Mateen; He is very strong and never gets tired or weak. When we are scared or feel we can’t do something good, we can ask Him to make us strong and firm."
    ],
